const body = $input.first().json.body || $input.first().json;
let target = (body.target || body.url || body.domain || body.ip || '').trim();
if (!target) throw new Error('Missing: target');
let scanType = (body.type || '').trim().toLowerCase();
if (!scanType) {
  scanType = /^\d{1,3}(\.\d{1,3}){3}$/.test(target) ? 'ip' : 'domain';
}
if (scanType === 'domain') {
  target = target.replace(/^https?:\/\//i,'').replace(/^www\./i,'').split('/')[0].split('?')[0].trim();
}
return [{ json: { target, type: scanType, triggered_at: new Date().toISOString() } }];

const scan = $input.first().json;
const threatLevel = scan.threat_level || 'UNKNOWN';
const alerts = scan.alerts_sent || {};
const emoji = { CRITICAL:'🔴', HIGH:'🟠', MEDIUM:'🟡', LOW:'🟢', CLEAN:'✅' }[threatLevel] || '⚪';
const aiAnalysis = scan.ai_analysis || '';
const summary = aiAnalysis.split('\n').map(l=>l.replace(/\*\*/g,'').trim()).find(l=>l.length>20 && !l.toUpperCase().includes('THREAT SUMMARY')) || aiAnalysis.slice(0,250);
return [{ json: {
  status: 'complete',
  scan_id: scan.scan_id || 'N/A',
  target: scan.target || 'N/A',
  target_type: scan.target_type || 'N/A',
  threat_level: threatLevel,
  threat_emoji: emoji,
  summary: summary || 'No summary',
  tg_sent: alerts.telegram?.status === 'sent',
  tg_screenshot_sent: alerts.telegram_screenshot?.status === 'sent',
  tg_pdf_sent: alerts.telegram_pdf?.status === 'sent',
  pdf_url: scan.pdf_url || null,
  tokens_used: scan.tokens_used || 0,
  completed_at: scan.completed_at || new Date().toISOString()
}}];
